    /**
     *Read or Store Electronic Journal Report from receipt number to receipt number and document content. FlagsReceipts is a char with bits representing the receipt types. FlagsReports is a char with bits representing the report type.
     * @param  optionStorageReport
     *         1 character with value 
     *  - 'j0' - To PC 
     *  - 'j2' - To USB Flash Drive 
     *  - 'j4' - To SD card
     * @param  flagsReceipts
     *         1 symbol for Receipts included in EJ: 
     * Flags.7=0 
     * Flags.6=1 
     * Flags.5=0  
     * Flags.4=0  
     * Flags.3=0  
     * Flags.2=0  
     * Flags.1=1 Yes, Flags.1=0 No (Include Invoice) 
     * Flags.0=1 Yes, Flags.0=0 No (Include Fiscal Rcp)
     * @param  flagsReports
     *         1 symbol for Reports included in EJ: 
     * Flags.7=0 
     * Flags.6=1 
     * Flags.5=0 
     * Flags.4=0 
     * Flags.3=1 Yes, Flags.3=0 No (Include Non-Fiscal Rcp) 
     * Flags.2=0 
     * Flags.1=1 Yes, Flags.1=0 No (Include Daily Z) 
     * Flags.0=1 Yes, Flags.0=0 No (Include Duplicates)
     * @param  startRcpNum
     *         6 symbols for initial receipt number included in report in format ######.
     * @param  endRcpNum
     *         6 symbols for final receipt number included in report in format ######.
     * @throws java.lang.Exception
     */
     public void ReadEJByReceiptNumCustom(final OptionStorageReport optionStorageReport, final byte flagsReceipts, final byte flagsReports, final Double startRcpNum, final Double endRcpNum) throws Exception {
             Do("ReadEJByReceiptNumCustom", "OptionStorageReport", optionStorageReport, "FlagsReceipts", flagsReceipts, "FlagsReports", flagsReports, "StartRcpNum", startRcpNum, "EndRcpNum", endRcpNum);
     }

